interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Operations Review",
  labelColor: "SECONDARY",
  showWhen: ri!isDPP,
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: {
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: {"To be completed by DPP Operations"},
          size: "SMALL",
          style: "EMPHASIS"
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          showDividers: true,
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Is additional follow up required?",
                  labelPosition: "ABOVE",
                  choiceLabels: {"Yes", "No"},
                  choiceValues: {true, false},
                  choiceLayout: "COMPACT",
                  value: index(ri!nomination, "isAdditionalFollowUpReq", null),
                  saveInto: {
                    ri!nomination.isAdditionalFollowUpReq,
                    /*if(*/
                      /*ri!nomination.isAdditionalFollowUpReq = false,*/
                      /*a!save(*/
                        /*ri!nomination.isAdditionalFollowUpReqCompleted,*/
                        /*false*/
                      /*),*/
                      /*null*/
                    /*)*/
                  }
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  showWhen: index(ri!nomination, "isReapprovedByBUCompleted", toboolean(null)) = true,
                  label: "",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text:"Does the nomination need to be reapproved by the BU?   ",
                      style: "STRONG"
                    ),
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "check-circle",
                      linkStyle: "STANDALONE",
                      color: "POSITIVE",
                      size: "MEDIUM"
                    ),
                  }
                ),
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Does the nomination need to be reapproved by the BU?",
                  showWhen: or(
                    index(ri!nomination, "isReapprovedByBUCompleted", toboolean(null)) = false,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(ri!nomination, "isReapprovedByBUCompleted", toboolean(null)))
                  ),
                  labelPosition: "ABOVE",
                  choiceLabels: {"Yes", "No"},
                  choiceValues: {true, false},
                  choiceLayout: "COMPACT",
                  disabled: or(
                    #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472947"(
                      nomination: ri!nomination,
                      currentReview: "isReapprovedByBU"
                    ),
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!selectedReviewer) = false
                  ),
                  value: index(ri!nomination, "isReapprovedByBU", null),
                  saveInto: {
                    ri!nomination.isReapprovedByBU
                  }
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  showWhen: index(ri!nomination, "isInspectionsReviewCompleted", toboolean(null)) = true,
                  label: "",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text:"Send to Inspections for review   ",
                      style: "STRONG"
                    ),
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "check-circle",
                      linkStyle: "STANDALONE",
                      color: "POSITIVE",
                      size: "MEDIUM"
                    ),
                  }
                ),
                #"SYSTEM_SYSRULES_checkboxField"(
                  label:"Send to Inspections for review",
                  showWhen: or(
                    index(ri!nomination, "isInspectionsReviewCompleted", toboolean(null)) = false,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(ri!nomination, "isInspectionsReviewCompleted", toboolean(null)))
                  ),
                  disabled: or(
                    #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472947"(
                      nomination: ri!nomination,
                      currentReview: "isInspectionsReview"
                    ),
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!selectedReviewer) = false, 
                    /*ri!nomination.subPositionTypeId = cons!CAW_INT_NOMINATION_SUBTYPE_POSITION_CORE_PARTNER,*/
                    /*ri!nomination.subPositionTypeId = cons!CAW_INT_NOMINATION_SUBTYPE_POSITION_CORE_MD*/
                  ),
                  choiceLabels:"" ,
                  choiceValues: true,
                  value: index(ri!nomination, "isInspectionsReview", null),
                  saveInto: {
                    ri!nomination.isInspectionsReview
                  }
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  showWhen: index(ri!nomination, "isHRReviewCompleted", toboolean(null)) = true,
                  label: "",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text:"Send to HR for review   ",
                      style: "STRONG"
                    ),
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "check-circle",
                      linkStyle: "STANDALONE",
                      color: "POSITIVE",
                      size: "MEDIUM"
                    ),
                  }
                ),
                #"SYSTEM_SYSRULES_checkboxField"(
                  label:"Send to HR for review",
                  showWhen: or(
                    index(ri!nomination, "isHRReviewCompleted", toboolean(null)) = false,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(ri!nomination, "isHRReviewCompleted", toboolean(null)))
                  ),
                  disabled: or(
                    #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472947"(
                      nomination: ri!nomination,
                      currentReview: "isHRReview"
                    ),
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!selectedReviewer) = false
                  ),
                  choiceLabels:"" ,
                  choiceValues: true,
                  value: index(ri!nomination, "isHRReview", null),
                  saveInto: {
                    ri!nomination.isHRReview
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_paragraphField"(
          label: "Operations Comments",
          labelPosition: "ABOVE",
          characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
          value: index(ri!nomination, "operationsComments", null),
          saveInto: {
            ri!nomination.operationsComments
          },
          refreshAfter: "UNFOCUS",
          height: "MEDIUM",
          required: or(
            index(ri!nomination, "isAdditionalFollowUpReq", null)=true,
            index(ri!nomination, "isReapprovedByBU", null)=true
          )
        )
      }
    )
  },
  isCollapsible: true,
  divider: "ABOVE",
  dividerWeight: "THIN",
  marginBelow: "STANDARD"
),
